"""
RAPP Workshop Optional Extension

Drop this one file into the local RAPP Brainstem agents/ folder or import it
through the Brainstem UI. It carries the workshop prototyper and Copilot Studio
solution packager as compressed, standard-library payloads.

Core workshop use stays local. This optional extension can:
- build a local, static M365-style click-through demo from a prototype use case;
- generate and test local agent.py files;
- export an import-ready Copilot Studio solution ZIP;
- deploy only when a separately authorized environment/settings file is present.

No credentials are embedded. Direct deployment reads credentials only from the
existing local settings mechanisms. Without credentials, packaging still
returns the local HTML demo and solution ZIP for manual import later.
"""

from __future__ import annotations

from base64 import b85decode
from hashlib import sha256
import importlib.util
import json
import os
from pathlib import Path
import sys
import zlib

try:
    from agents.basic_agent import BasicAgent
except ImportError:
    try:
        from basic_agent import BasicAgent
    except ImportError:
        class BasicAgent:
            def __init__(self, name=None, metadata=None):
                self.name = name or self.__class__.__name__
                self.metadata = metadata or {}


